package com.dukaops.backend.contact; import java.util.UUID; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.dukaops.backend.auth.TenantUserPrincipal; import com.dukaops.backend.contact.dto.*;
@RestController @RequestMapping("/api/contacts") public class ContactController {private final ContactService service; public ContactController(ContactService s){service=s;} @GetMapping("/customers") public Page<ContactResponse> customers(@AuthenticationPrincipal TenantUserPrincipal a,@RequestParam(required=false)String search,@RequestParam(required=false)ContactStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.customers(a,search,status,page,size);} @PostMapping("/customers") public ContactResponse createCustomer(@AuthenticationPrincipal TenantUserPrincipal a,@Valid @RequestBody CustomerRequest r){return service.createCustomer(a,r);} @PutMapping("/customers/{id}") public ContactResponse updateCustomer(@AuthenticationPrincipal TenantUserPrincipal a,@PathVariable UUID id,@Valid @RequestBody CustomerRequest r){return service.updateCustomer(a,id,r);} @PatchMapping("/customers/{id}/status") public ContactResponse customerStatus(@AuthenticationPrincipal TenantUserPrincipal a,@PathVariable UUID id,@RequestParam ContactStatus status){return service.statusCustomer(a,id,status);} @GetMapping("/suppliers") public Page<ContactResponse> suppliers(@AuthenticationPrincipal TenantUserPrincipal a,@RequestParam(required=false)String search,@RequestParam(required=false)ContactStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.suppliers(a,search,status,page,size);} @PostMapping("/suppliers") public ContactResponse createSupplier(@AuthenticationPrincipal TenantUserPrincipal a,@Valid @RequestBody SupplierRequest r){return service.createSupplier(a,r);} @PutMapping("/suppliers/{id}") public ContactResponse updateSupplier(@AuthenticationPrincipal TenantUserPrincipal a,@PathVariable UUID id,@Valid @RequestBody SupplierRequest r){return service.updateSupplier(a,id,r);} @PatchMapping("/suppliers/{id}/status") public ContactResponse supplierStatus(@AuthenticationPrincipal TenantUserPrincipal a,@PathVariable UUID id,@RequestParam ContactStatus status){return service.statusSupplier(a,id,status);} }
